<script setup lang="ts">import {ref,onMounted} from 'vue';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {createRun} from '../api/runs';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StudySelect from '../components/StudySelect.vue';import RunTable from '../components/RunTable.vue';const lab=useResearch(),auth=useAuth(),data=ref({name:'窑程A · 因子与全家族复核',study_id:0,alpha:.05,contrast_family:'all_simple_pairwise'}),message=ref(''),{busy,error,perform}=useTask();onMounted(()=>perform(async()=>{await lab.load();data.value.study_id=lab.studies[0]?.id||0;}));usePolling(async()=>{if(lab.runs.some(r=>['queued','running'].includes(r.status)))await lab.load();});function submit(){perform(async()=>{const r=await createRun(data.value);message.value=`分析 #${r.id} 已进入计算队列，全部预设对比会一并保留。`;await lab.load();});}</script><template><PageHeading index="03" title="在计算之前，把比较家族写清楚" text="主效应、交互与全部简单效应一起报告，避免事后只挑显著结果。"/><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="config-layout"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><h2>新建因子分析</h2><label>分析名称<input v-model="data.name" required minlength="2"></label><StudySelect v-model="data.study_id" :studies="lab.studies"/><label>检验alpha / 逐项区间水平<select v-model="data.alpha"><option :value=".01">.01 / 99%逐项区间</option><option :value=".05">.05 / 95%逐项区间</option><option :value=".1">.10 / 90%逐项区间</option></select></label><div class="fixed-family"><b>固定全部简单效应</b><p>每个釉层内所有温度两两差异，加上每个温度内所有釉层两两差异。3×2设计共9项，同一家族Holm校正。</p></div><button class="primary" :disabled="busy">提交ANOVA与预设对比 →</button><p v-if="message" role="status" class="success">{{message}}</p></form><section v-else class="research-form"><h2>当前为观察权限</h2><p>可读取全部分析和下载获批提案；提交分析需要材料分析员或负责人权限。</p></section><aside class="method-notes"><p class="eyebrow">MODEL / FIXED EFFECTS</p><h2>处理格完整，<br>平方和才按此分解。</h2><div class="formula">Y = μ + A + B + A×B + ε</div><ol><li><b>设计前提</b><p>完整平衡、每格≥3个随机独立试片；固定效应，不用于重复测量或随机窑批推断。</p></li><li><b>统一残差尺度</b><p>各F检验使用格内MSE；简单差值t检验和逐项区间使用同一MSE与残差自由度。</p></li><li><b>区间和校正各有口径</b><p>Holm控制预设简单效应家族p值；显示的t区间是逐项区间，不具备家族同时覆盖保证。</p></li></ol></aside></div><section class="run-directory"><div class="section-heading"><h2>计算与失败记录</h2><span>零残差方差保留不可估原因</span></div><RunTable :runs="lab.runs"/></section></template>
